/* @socom-skeleton body Init__4CSndFv */
void CSnd::Init()
{
	if (m_isDisabled)
	{
		return;
	}

	if (!vagArchiveIsOpen)
	{
		vagArchiveIsOpen = true;
		m_vagArchive.Open("RUN\\SOUNDS\\VAGSTORE.ZAR", 0, 0x21, 16);
		m_vagArchive.CloseKeepDir();
	}
}

