/* @socom-skeleton body vagReadOffset__4CSndFPCcRUiRUi */
bool CSnd::vagReadOffset(const char* name, u32& offset, u32& size)
{
	if (m_isDisabled)
	{
		return false;
	}

	zar::CKey* key = m_vagArchive.FindKey(name);
	
	if (key)
	{
		offset = key->GetOffset();
		size = key->GetSize();
		m_vagArchive.CloseKey(key);
		return true;
	}
	
	return false;
}

